/**
 * Server-side data fetcher for WeekRevenueTrajectoryWidget.
 * Aggregates payments.amount_cents by calendar day for the current ISO week (Mon–Sun).
 * Also computes delta vs the same day range in the previous week.
 */

type SupabaseClient = Awaited<ReturnType<typeof import('@/lib/supabase/server').createClient>>

// ─── Types ────────────────────────────────────────────────────────────────────

export interface DayRevenue {
  /** YYYY-MM-DD */
  date: string
  /** total collected in cents */
  amountCents: number
  /** booking count that contributed to this day's payments */
  bookingCount: number
}

export interface WeekRevenueData {
  days: DayRevenue[]
  /** Sum of this week so far — cents */
  totalCents: number
  /** Sum of equivalent days last week — cents */
  prevTotalCents: number
  /** Delta percent vs prev week (null when prev was 0) */
  deltaPercent: number | null
  /** Mon-0 index of "today" within the week (0=Mon … 6=Sun) */
  todayIndex: number
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

/**
 * Returns Monday 00:00:00 UTC for the ISO week containing `ref`.
 * JS getDay(): 0=Sun 1=Mon … 6=Sat  →  ISO: Mon is first day.
 */
function isoWeekMonday(ref: Date): Date {
  const d = new Date(ref)
  d.setUTCHours(0, 0, 0, 0)
  const day = d.getUTCDay() // 0=Sun
  const diffToMon = day === 0 ? -6 : 1 - day
  d.setUTCDate(d.getUTCDate() + diffToMon)
  return d
}

function addDays(d: Date, n: number): Date {
  const result = new Date(d)
  result.setUTCDate(result.getUTCDate() + n)
  return result
}

// ─── Main fetch ───────────────────────────────────────────────────────────────

export async function getWeekRevenueData(
  supabase: SupabaseClient,
  studioId: string,
): Promise<WeekRevenueData> {
  const now = new Date()
  const thisMonday = isoWeekMonday(now)
  const nextMonday = addDays(thisMonday, 7)
  const prevMonday = addDays(thisMonday, -7)

  // ── This week's payments ──
  const { data: thisWeekPayments } = await supabase
    .from('payments')
    .select('amount_cents, created_at, booking_id')
    .eq('studio_id', studioId)
    .eq('status', 'succeeded')
    .neq('type', 'refund')
    .gte('created_at', thisMonday.toISOString())
    .lt('created_at', nextMonday.toISOString())

  // ── Previous week's payments ──
  const { data: prevWeekPayments } = await supabase
    .from('payments')
    .select('amount_cents, created_at')
    .eq('studio_id', studioId)
    .eq('status', 'succeeded')
    .neq('type', 'refund')
    .gte('created_at', prevMonday.toISOString())
    .lt('created_at', thisMonday.toISOString())

  // ── Build daily buckets for this week ──
  const buckets = new Map<string, { amountCents: number; bookingIds: Set<string> }>()
  for (let i = 0; i < 7; i++) {
    const d = addDays(thisMonday, i)
    const key = d.toISOString().slice(0, 10)
    buckets.set(key, { amountCents: 0, bookingIds: new Set() })
  }

  for (const p of thisWeekPayments ?? []) {
    const key = p.created_at.slice(0, 10)
    const bucket = buckets.get(key)
    if (bucket) {
      bucket.amountCents += p.amount_cents
      if (p.booking_id) bucket.bookingIds.add(p.booking_id)
    }
  }

  const days: DayRevenue[] = []
  for (let i = 0; i < 7; i++) {
    const d = addDays(thisMonday, i)
    const key = d.toISOString().slice(0, 10)
    const bucket = buckets.get(key) ?? { amountCents: 0, bookingIds: new Set() }
    days.push({
      date: key,
      amountCents: bucket.amountCents,
      bookingCount: bucket.bookingIds.size,
    })
  }

  const totalCents = days.reduce((s, d) => s + d.amountCents, 0)

  const prevTotalCents = (prevWeekPayments ?? []).reduce(
    (s, p) => s + p.amount_cents,
    0,
  )

  const deltaPercent =
    prevTotalCents === 0
      ? null
      : Math.round(((totalCents - prevTotalCents) / prevTotalCents) * 100)

  // todayIndex: 0=Mon … 6=Sun (matches days array index)
  const nowDay = now.getUTCDay() // 0=Sun
  const todayIndex = nowDay === 0 ? 6 : nowDay - 1

  return { days, totalCents, prevTotalCents, deltaPercent, todayIndex }
}

/**
 * Server-side data fetcher for ArtistUtilizationWidget.
 * Computes booked minutes / scheduled available minutes * 100 per artist this week.
 */

type SupabaseClient = Awaited<ReturnType<typeof import('@/lib/supabase/server').createClient>>

// ─── Types ────────────────────────────────────────────────────────────────────

export interface ArtistUtilRow {
  artistId: string
  name: string
  /** URL to artist avatar (may be null) */
  avatarUrl: string | null
  /** 'staff' | 'guest' */
  type: 'staff' | 'guest'
  /** 0–100 */
  utilizationPct: number
  bookedMinutes: number
  availableMinutes: number
}

export interface ArtistUtilizationData {
  rows: ArtistUtilRow[]
  weekLabel: string
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

function isoWeekMonday(ref: Date): Date {
  const d = new Date(ref)
  d.setUTCHours(0, 0, 0, 0)
  const day = d.getUTCDay()
  const diffToMon = day === 0 ? -6 : 1 - day
  d.setUTCDate(d.getUTCDate() + diffToMon)
  return d
}

// ─── Main fetch ───────────────────────────────────────────────────────────────

export async function getArtistUtilizationData(
  supabase: SupabaseClient,
  studioId: string,
): Promise<ArtistUtilizationData> {
  const now = new Date()
  const weekStart = isoWeekMonday(now)
  const weekEnd = new Date(weekStart)
  weekEnd.setUTCDate(weekEnd.getUTCDate() + 7)

  const startIso = weekStart.toISOString()
  const endIso = weekEnd.toISOString()

  // Fetch artists + their bookings this week in parallel
  const [artistsRes, bookingsRes] = await Promise.all([
    supabase
      .from('artists')
      .select('id, display_name, avatar_url, type')
      .eq('studio_id', studioId)
      .eq('is_active', true),

    supabase
      .from('bookings')
      .select('artist_id, duration_min, status, scheduled_at')
      .eq('studio_id', studioId)
      .gte('scheduled_at', startIso)
      .lt('scheduled_at', endIso)
      .in('status', ['confirmed', 'completed', 'in_progress']),
  ])

  const artists = artistsRes.data ?? []
  const bookings = bookingsRes.data ?? []

  // Default available hours per artist for the week if no schedule data: 8h × 5 days
  const DEFAULT_WEEKLY_AVAILABLE_MINUTES = 8 * 60 * 5

  // Aggregate booked minutes per artist
  const bookedMap = new Map<string, number>()
  for (const b of bookings) {
    const current = bookedMap.get(b.artist_id) ?? 0
    bookedMap.set(b.artist_id, current + (b.duration_min ?? 0))
  }

  const rows: ArtistUtilRow[] = artists.map((a) => {
    const bookedMinutes = bookedMap.get(a.id) ?? 0
    const availableMinutes = DEFAULT_WEEKLY_AVAILABLE_MINUTES
    const utilizationPct = Math.min(
      100,
      Math.round((bookedMinutes / availableMinutes) * 100),
    )

    return {
      artistId: a.id,
      name: a.display_name,
      avatarUrl: a.avatar_url ?? null,
      type: (a.type === 'guest' ? 'guest' : 'staff') as 'staff' | 'guest',
      utilizationPct,
      bookedMinutes,
      availableMinutes,
    }
  })

  // Sort: highest utilization first
  rows.sort((a, b) => b.utilizationPct - a.utilizationPct)

  const weekLabel = weekStart.toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
  })

  return { rows, weekLabel }
}

/**
 * Server-side data fetcher for PendingDepositsWidget.
 * Finds confirmed upcoming bookings where deposit_paid=false, ordered by soonest.
 */

type SupabaseClient = Awaited<ReturnType<typeof import('@/lib/supabase/server').createClient>>

// ─── Types ────────────────────────────────────────────────────────────────────

export interface PendingDepositRow {
  bookingId: string
  clientName: string
  /** ISO string */
  scheduledAt: string
  depositCents: number
  /** e.g. "overdue 2h" or "Fri · 2 days left" */
  dueLabel: string
  isOverdue: boolean
}

export interface PendingDepositsData {
  rows: PendingDepositRow[]
  totalCents: number
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

function buildDueLabel(scheduledAt: string): { label: string; isOverdue: boolean } {
  const now = Date.now()
  const sessionMs = new Date(scheduledAt).getTime()
  const diffMs = sessionMs - now

  if (diffMs < 0) {
    // Past session
    const hoursAgo = Math.round(Math.abs(diffMs) / (1000 * 60 * 60))
    return { label: `overdue ${hoursAgo}h`, isOverdue: true }
  }

  const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24))
  if (diffDays === 0) {
    const diffHours = Math.round(diffMs / (1000 * 60 * 60))
    return { label: `today · ${diffHours}h left`, isOverdue: false }
  }

  const dayName = new Date(scheduledAt).toLocaleDateString('en-US', { weekday: 'short' })
  return { label: `${dayName} · ${diffDays} day${diffDays !== 1 ? 's' : ''} left`, isOverdue: false }
}

// ─── Main fetch ───────────────────────────────────────────────────────────────

export async function getPendingDepositsData(
  supabase: SupabaseClient,
  studioId: string,
): Promise<PendingDepositsData> {
  const { data } = await supabase
    .from('bookings')
    .select(`
      id,
      scheduled_at,
      deposit_cents,
      clients!inner(first_name, last_name)
    `)
    .eq('studio_id', studioId)
    .eq('deposit_paid', false)
    .gt('deposit_cents', 0)
    .eq('status', 'confirmed')
    .order('scheduled_at', { ascending: true })
    .limit(5)

  type Row = {
    id: string
    scheduled_at: string
    deposit_cents: number
    clients: { first_name: string; last_name: string | null }
  }

  const rows: PendingDepositRow[] = ((data ?? []) as Row[]).map((r) => {
    const { label, isOverdue } = buildDueLabel(r.scheduled_at)
    const client = Array.isArray(r.clients) ? r.clients[0] : r.clients
    return {
      bookingId: r.id,
      clientName: `${client?.first_name ?? ''} ${client?.last_name ?? ''}`.trim(),
      scheduledAt: r.scheduled_at,
      depositCents: r.deposit_cents,
      dueLabel: label,
      isOverdue,
    }
  })

  const totalCents = rows.reduce((s, r) => s + r.depositCents, 0)

  return { rows, totalCents }
}

/**
 * Server-side data fetcher for ConsentStatusWidget.
 * Counts signed vs unsigned consent for bookings this week.
 */

type SupabaseClient = Awaited<ReturnType<typeof import('@/lib/supabase/server').createClient>>

// ─── Types ────────────────────────────────────────────────────────────────────

export interface UnsignedConsentRow {
  bookingId: string
  clientName: string
  /** ISO string */
  scheduledAt: string
}

export interface ConsentStatusData {
  signedCount: number
  totalCount: number
  unsignedRows: UnsignedConsentRow[]
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

function isoWeekMonday(ref: Date): Date {
  const d = new Date(ref)
  d.setUTCHours(0, 0, 0, 0)
  const day = d.getUTCDay()
  const diffToMon = day === 0 ? -6 : 1 - day
  d.setUTCDate(d.getUTCDate() + diffToMon)
  return d
}

// ─── Main fetch ───────────────────────────────────────────────────────────────

export async function getConsentStatusData(
  supabase: SupabaseClient,
  studioId: string,
): Promise<ConsentStatusData> {
  const now = new Date()
  const weekStart = isoWeekMonday(now)
  const weekEnd = new Date(weekStart)
  weekEnd.setUTCDate(weekEnd.getUTCDate() + 7)

  const startIso = weekStart.toISOString()
  const endIso = weekEnd.toISOString()

  const { data } = await supabase
    .from('bookings')
    .select(`
      id,
      scheduled_at,
      consent_signed_at,
      clients!inner(first_name, last_name)
    `)
    .eq('studio_id', studioId)
    .gte('scheduled_at', startIso)
    .lt('scheduled_at', endIso)
    .in('status', ['confirmed', 'pending', 'in_progress', 'completed'])
    .order('scheduled_at', { ascending: true })

  type Row = {
    id: string
    scheduled_at: string
    consent_signed_at: string | null
    clients: { first_name: string; last_name: string | null }
  }

  const rows = (data ?? []) as Row[]
  const totalCount = rows.length
  const signedCount = rows.filter((r) => r.consent_signed_at !== null).length

  const unsignedRows: UnsignedConsentRow[] = rows
    .filter((r) => r.consent_signed_at === null)
    .slice(0, 10)
    .map((r) => {
      const client = Array.isArray(r.clients) ? r.clients[0] : r.clients
      return {
        bookingId: r.id,
        clientName: `${client?.first_name ?? ''} ${client?.last_name ?? ''}`.trim(),
        scheduledAt: r.scheduled_at,
      }
    })

  return { signedCount, totalCount, unsignedRows }
}

/**
 * Server-side data fetcher for LowInventoryWidget.
 * Returns inventory items below their reorder threshold.
 * Returns null when no items are below threshold (widget should not render).
 */

type SupabaseClient = Awaited<ReturnType<typeof import('@/lib/supabase/server').createClient>>

// ─── Types ────────────────────────────────────────────────────────────────────

export interface LowInventoryRow {
  itemId: string
  name: string
  sku: string | null
  currentStock: number
  reorderThreshold: number
  /** Days since last reorder, or null if no reorder history */
  daysSinceReorder: number | null
}

export interface LowInventoryData {
  rows: LowInventoryRow[]
}

// ─── Main fetch ───────────────────────────────────────────────────────────────

export async function getLowInventoryData(
  supabase: SupabaseClient,
  studioId: string,
): Promise<LowInventoryData | null> {
  const { data } = await supabase
    .from('inventory_items')
    .select('id, name, sku, quantity_on_hand, reorder_threshold, last_reorder_at')
    .eq('studio_id', studioId)
    .eq('is_active', true)
    .filter('quantity_on_hand', 'lt', 'reorder_threshold')
    .order('quantity_on_hand', { ascending: true })
    .limit(6)

  if (!data || data.length === 0) return null

  type Row = {
    id: string
    name: string
    sku: string | null
    quantity_on_hand: number
    reorder_threshold: number
    last_reorder_at: string | null
  }

  const rows: LowInventoryRow[] = (data as Row[]).map((r) => {
    let daysSinceReorder: number | null = null
    if (r.last_reorder_at) {
      const diffMs = Date.now() - new Date(r.last_reorder_at).getTime()
      daysSinceReorder = Math.floor(diffMs / (1000 * 60 * 60 * 24))
    }
    return {
      itemId: r.id,
      name: r.name,
      sku: r.sku,
      currentStock: r.quantity_on_hand,
      reorderThreshold: r.reorder_threshold,
      daysSinceReorder,
    }
  })

  return { rows }
}

/**
 * Server-side data fetcher for GuestResidencyWidget.
 * Returns active guest artist residencies.
 * Returns null when no active residencies exist (widget should not render).
 *
 * TODO: Schema requires `type='guest'` + `residency_end_at` on the artists table.
 * If these columns don't exist yet, the widget renders empty/null gracefully.
 */

type SupabaseClient = Awaited<ReturnType<typeof import('@/lib/supabase/server').createClient>>

// ─── Types ────────────────────────────────────────────────────────────────────

export interface GuestResidencyRow {
  artistId: string
  name: string
  avatarUrl: string | null
  residencyEndAt: string
  daysRemaining: number
  bookingsDuringResidency: number
}

export interface GuestResidencyData {
  rows: GuestResidencyRow[]
}

// ─── Main fetch ───────────────────────────────────────────────────────────────

export async function getGuestResidencyData(
  supabase: SupabaseClient,
  studioId: string,
): Promise<GuestResidencyData | null> {
  // Attempt to query; if columns don't exist the query returns empty
  const nowIso = new Date().toISOString()

  const { data, error } = await supabase
    .from('artists')
    .select('id, display_name, avatar_url, residency_end_at')
    .eq('studio_id', studioId)
    .eq('type', 'guest')
    .eq('is_active', true)
    .gt('residency_end_at', nowIso)
    .order('residency_end_at', { ascending: true })
    .limit(5)

  // Column may not exist yet — treat as empty
  if (error || !data || data.length === 0) return null

  type Row = {
    id: string
    display_name: string
    avatar_url: string | null
    residency_end_at: string
  }

  const artistIds = (data as Row[]).map((r) => r.id)

  // Booking counts during each residency (current week as proxy for simplicity)
  const weekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString()
  const { data: bookingCounts } = await supabase
    .from('bookings')
    .select('artist_id')
    .eq('studio_id', studioId)
    .in('artist_id', artistIds)
    .gte('scheduled_at', weekAgo)
    .in('status', ['confirmed', 'completed', 'in_progress'])

  const countMap = new Map<string, number>()
  for (const b of bookingCounts ?? []) {
    countMap.set(b.artist_id, (countMap.get(b.artist_id) ?? 0) + 1)
  }

  const rows: GuestResidencyRow[] = (data as Row[]).map((r) => {
    const endMs = new Date(r.residency_end_at).getTime()
    const daysRemaining = Math.max(0, Math.ceil((endMs - Date.now()) / (1000 * 60 * 60 * 24)))
    return {
      artistId: r.id,
      name: r.display_name,
      avatarUrl: r.avatar_url,
      residencyEndAt: r.residency_end_at,
      daysRemaining,
      bookingsDuringResidency: countMap.get(r.id) ?? 0,
    }
  })

  return { rows }
}

