import { useRouter } from 'next/navigation'
import { cn } from '@/lib/utils'
import { formatCurrency } from '@/lib/utils'
import type { WeekRevenueData } from '@/lib/dashboard/week-revenue'

// ─── Types ────────────────────────────────────────────────────────────────────

interface WeekRevenueTrajectoryWidgetProps {
  data: WeekRevenueData
  preview?: boolean
}

// ─── Day labels ───────────────────────────────────────────────────────────────

const DAY_LABELS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'] as const

// ─── Bar ─────────────────────────────────────────────────────────────────────

interface BarProps {
  day: (typeof DAY_LABELS)[number]
  amountCents: number
  bookingCount: number
  date: string
  heightPct: number
  isToday: boolean
  isFuture: boolean
  preview: boolean
  onClick: () => void
}

function RevenueBar({
  day,
  amountCents,
  bookingCount,
  date,
  heightPct,
  isToday,
  isFuture,
  preview,
  onClick,
}: BarProps) {
  const MIN_HEIGHT = 4 // px — always visible

  const barClass = cn(
    'w-full rounded-t-sm transition-opacity duration-150',
    isToday
      ? 'bg-[var(--color-onyx)]'
      : isFuture
        ? 'bg-[var(--color-border)]'
        : 'bg-[rgba(178,58,43,0.25)]',
  )

  return (
    <button
      type="button"
      onClick={onClick}
      disabled={preview || isFuture}
      aria-label={`${day}: ${formatCurrency(amountCents)}, ${bookingCount} booking${bookingCount !== 1 ? 's' : ''}`}
      className="group relative flex flex-1 flex-col items-center gap-1 focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-[var(--color-ring)] focus-visible:ring-offset-1 rounded"
    >
      {/* Tooltip */}
      {!preview && !isFuture && (
        <div
          aria-hidden="true"
          className="pointer-events-none absolute bottom-full mb-1.5 left-1/2 -translate-x-1/2 z-10 hidden group-hover:flex flex-col items-center"
        >
          <div className="rounded bg-[var(--color-onyx)] px-2 py-1 text-[10px] text-[var(--color-bone)] whitespace-nowrap shadow-[var(--shadow-lift)]">
            {formatCurrency(amountCents)} · {bookingCount} booking{bookingCount !== 1 ? 's' : ''}
          </div>
          <div className="h-1.5 w-1.5 -mt-0.5 rotate-45 bg-[var(--color-onyx)]" />
        </div>
      )}

      {/* Bar container */}
      <div className="flex h-16 w-full items-end">
        <div
          className={barClass}
          style={{ height: `${Math.max(heightPct, 0) * 64 / 100 + MIN_HEIGHT}px` }}
        />
      </div>

      {/* Label */}
      <span
        className={cn(
          'text-[9px] font-bold uppercase tracking-[0.08em]',
          isToday ? 'text-[var(--color-foreground)]' : 'text-[var(--color-muted-foreground)]',
        )}
      >
        {day}
      </span>

      {/* Today dot */}
      {isToday && (
        <span
          aria-hidden="true"
          className="absolute -bottom-3 left-1/2 h-1 w-1 -translate-x-1/2 rounded-full bg-[var(--color-rust)]"
        />
      )}
    </button>
  )
}

// ─── Widget ───────────────────────────────────────────────────────────────────

export function WeekRevenueTrajectoryWidget({
  data,
  preview = false,
}: WeekRevenueTrajectoryWidgetProps) {
  const router = useRouter()

  const maxCents = Math.max(...data.days.map((d) => d.amountCents), 1)

  const deltaLabel =
    data.deltaPercent === null
      ? null
      : data.deltaPercent >= 0
        ? `+${data.deltaPercent}% vs last week`
        : `${data.deltaPercent}% vs last week`

  const isPositive = (data.deltaPercent ?? 0) >= 0

  return (
    <div
      className="flex flex-col rounded-xl border border-[var(--color-border)] bg-[var(--color-card)] p-5 shadow-[var(--shadow-card)]"
      role="region"
      aria-label="Revenue this week"
    >
      {/* Header */}
      <div className="flex items-center justify-between gap-2">
        <p className="text-[11px] font-bold uppercase tracking-[0.08em] text-[var(--color-muted-foreground)]">
          Revenue this week
        </p>
        {/* Period selector — This week is wired; others are scaffolded */}
        <span className="text-[11px] text-[var(--color-muted-foreground)] cursor-default select-none">
          This week
        </span>
      </div>

      {/* Big value */}
      <div className="mt-3 flex items-baseline gap-2">
        <p
          className={cn(
            'font-serif text-[32px] italic leading-none tabular-nums',
            preview ? 'text-[var(--color-muted-foreground)]' : 'text-[var(--color-foreground)]',
          )}
        >
          {preview ? '—' : formatCurrency(data.totalCents)}
        </p>
        {!preview && deltaLabel && (
          <span
            className={cn(
              'rounded-full px-2 py-0.5 text-[10px] font-medium',
              isPositive
                ? 'bg-[var(--color-success-bg)] text-[var(--color-success-foreground)]'
                : 'bg-[rgba(178,58,43,0.08)] text-[var(--color-rust)]',
            )}
          >
            {deltaLabel}
          </span>
        )}
      </div>

      {/* Bar chart */}
      <div className="mt-5 flex items-end gap-1" aria-hidden={preview}>
        {data.days.map((day, i) => {
          const heightPct = Math.round((day.amountCents / maxCents) * 100)
          const isFuture = i > data.todayIndex
          const isToday = i === data.todayIndex

          return (
            <RevenueBar
              key={day.date}
              day={DAY_LABELS[i] as (typeof DAY_LABELS)[number]}
              amountCents={day.amountCents}
              bookingCount={day.bookingCount}
              date={day.date}
              heightPct={heightPct}
              isToday={isToday}
              isFuture={isFuture}
              preview={preview}
              onClick={() => {
                if (!preview && !isFuture) {
                  router.push(`/payments?date=${day.date}`)
                }
              }}
            />
          )
        })}
      </div>
    </div>
  )
}

