// ─── Avatar ───────────────────────────────────────────────────────────────────

function ArtistAvatar({ name, avatarUrl }: { name: string; avatarUrl: string | null }) {
  const initials = name
    .split(' ')
    .map((p) => p[0] ?? '')
    .slice(0, 2)
    .join('')
    .toUpperCase()

  if (avatarUrl) {
    return (
      // eslint-disable-next-line @next/next/no-img-element
      <img
        src={avatarUrl}
        alt={name}
        className="h-7 w-7 rounded-full object-cover shrink-0"
      />
    )
  }

  return (
    <span
      aria-hidden="true"
      className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-[var(--color-muted)] text-[10px] font-semibold text-[var(--color-foreground)]"
    >
      {initials}
    </span>
  )
}

// ─── Utilization bar color ────────────────────────────────────────────────────

function utilBarClass(pct: number): string {
  if (pct >= 80) return 'bg-[var(--color-success)]'
  if (pct >= 40) return 'bg-[var(--color-stone)]'
  return 'bg-[var(--color-rust)]'
