import { useOptimistic, useTransition } from 'react'
import { cn } from '@/lib/utils'
import { formatCurrency } from '@/lib/utils'
import { sendDepositReminderAction } from '@/app/(app)/inbox/actions'
import { logger } from '@/lib/logger'
import type { PendingDepositsData } from '@/lib/dashboard/pending-deposits'

// ─── Types ────────────────────────────────────────────────────────────────────

interface PendingDepositsWidgetProps {
  data: PendingDepositsData
  preview?: boolean
}

// ─── Widget ───────────────────────────────────────────────────────────────────

export function PendingDepositsWidget({
  data,
  preview = false,
}: PendingDepositsWidgetProps) {
  // Track which booking IDs have had reminders sent (optimistic)
  const [sentIds, addSentId] = useOptimistic<string[], string>(
    [],
    (prev, id) => [...prev, id],
  )
  const [isPending, startTransition] = useTransition()
  void isPending

  function handleSendReminder(bookingId: string) {
    startTransition(async () => {
      addSentId(bookingId)
      try {
        await sendDepositReminderAction(bookingId)
      } catch (err) {
        logger.error({ err, bookingId }, 'pending-deposits: send reminder failed')
      }
    })
  }

  const visibleRows = data.rows.filter((r) => !sentIds.includes(r.bookingId))

  return (
    <div
      className="flex flex-col rounded-xl border border-[var(--color-border)] bg-[var(--color-card)] p-5 shadow-[var(--shadow-card)]"
      role="region"
      aria-label="Pending deposits"
    >
      {/* Header */}
      <div className="flex items-center justify-between gap-2">
        <p className="text-[11px] font-bold uppercase tracking-[0.08em] text-[var(--color-muted-foreground)]">
          Pending deposits
        </p>
        {!preview && data.totalCents > 0 && (
          <span className="text-[13px] font-semibold tabular-nums text-[var(--color-rust)]">
            {formatCurrency(data.totalCents)}
          </span>
        )}
      </div>

      {/* Rows */}
      <div className="mt-4">
        {preview ? (
          // Skeleton
          <div className="space-y-3">
            {Array.from({ length: 3 }).map((_, i) => (
              <div key={i} className="flex items-center justify-between gap-2">
                <div className="space-y-1">
                  <div className="h-3 w-20 rounded bg-[var(--color-muted)]" />
                  <div className="h-2.5 w-28 rounded bg-[var(--color-muted)]" />
                </div>
                <div className="h-3 w-12 rounded bg-[var(--color-muted)]" />
              </div>
            ))}
          </div>
        ) : visibleRows.length === 0 && sentIds.length === 0 ? (
          // Empty state — all clear
          <p className="text-[13px] text-[var(--color-muted-foreground)] italic">
            All deposits collected. Nice work.
          </p>
        ) : visibleRows.length === 0 ? (
          // All reminded this session
          <p className="text-[13px] text-[var(--color-muted-foreground)]">
            Reminders sent for all pending deposits.
          </p>
        ) : (
          <ul className="space-y-3" role="list">
            {visibleRows.map((row) => {
              const justSent = sentIds.includes(row.bookingId)

              return (
                <li
                  key={row.bookingId}
                  className="flex items-start justify-between gap-3"
                >
                  <div className="min-w-0">
                    <p className="truncate text-[13px] font-medium text-[var(--color-foreground)]">
                      {row.clientName}
                    </p>
                    <p
                      className={cn(
                        'text-[11px] tabular-nums',
                        row.isOverdue
                          ? 'text-[var(--color-rust)]'
                          : 'text-[var(--color-muted-foreground)]',
                      )}
                    >
                      {row.dueLabel}
                    </p>
                  </div>

                  <div className="flex shrink-0 flex-col items-end gap-1.5">
                    <span className="text-[12px] font-semibold tabular-nums text-[var(--color-foreground)]">
                      {formatCurrency(row.depositCents)}
                    </span>
                    {justSent ? (
                      <span className="rounded-full bg-[var(--color-success-bg)] px-1.5 py-0.5 text-[9px] font-semibold uppercase tracking-[0.06em] text-[var(--color-success-foreground)]">
                        Sent
                      </span>
                    ) : (
                      <button
                        type="button"
                        onClick={() => handleSendReminder(row.bookingId)}
                        className="rounded-full border border-[var(--color-border)] bg-transparent px-2 py-0.5 text-[9px] font-semibold uppercase tracking-[0.06em] text-[var(--color-foreground)] transition-colors hover:bg-[var(--color-muted)] focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-[var(--color-ring)]"
                      >
                        Send reminder
                      </button>
                    )}
                  </div>
                </li>
              )
            })}
          </ul>
        )}
      </div>
    </div>
  )
}

