              <span className="text-[var(--color-foreground)]">{data.signedCount}</span>
              <span className="text-[var(--color-muted-foreground)] text-[22px]">
                {' '}/ {data.totalCount}
              </span>
            </p>
            <p className="mt-1 text-[11px] text-[var(--color-muted-foreground)]">
