                          weekday: 'short',
                          month: 'short',
                          day: 'numeric',
                        })}
                      </p>
                    </div>
                    <button
                      type="button"
                      onClick={() => handleResend(row.bookingId)}
                      className={cn(
                        'shrink-0 rounded-full border border-[var(--color-border)] px-2 py-0.5 text-[9px] font-semibold uppercase tracking-[0.06em] text-[var(--color-foreground)]',
                        'transition-colors hover:bg-[var(--color-muted)] focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-[var(--color-ring)]',
                      )}
                    >
                      Resend
                    </button>
                  </li>
                ))}
