'use client'

import { useRouter } from 'next/navigation'
import { cn } from '@/lib/utils'
import type { GuestResidencyData } from '@/lib/dashboard/guest-residency'

// ─── Types ────────────────────────────────────────────────────────────────────

interface GuestResidencyWidgetProps {
  data: GuestResidencyData | null
  preview?: boolean
}

// ─── Avatar ───────────────────────────────────────────────────────────────────

function ArtistAvatar({ name, avatarUrl }: { name: string; avatarUrl: string | null }) {
  const initials = name
    .split(' ')
    .map((p) => p[0] ?? '')
    .slice(0, 2)
    .join('')
    .toUpperCase()

  if (avatarUrl) {
    return (
      // eslint-disable-next-line @next/next/no-img-element
      <img
        src={avatarUrl}
        alt={name}
        className="h-7 w-7 rounded-full object-cover shrink-0"
      />
    )
  }

  return (
    <span
      aria-hidden="true"
      className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-[var(--color-muted)] text-[10px] font-semibold text-[var(--color-foreground)]"
    >
      {initials}
    </span>
  )
}

// ─── Widget ───────────────────────────────────────────────────────────────────

export function GuestResidencyWidget({ data, preview = false }: GuestResidencyWidgetProps) {
  const router = useRouter()

  // Conditional: only render when there are active residencies
  if (!preview && (!data || data.rows.length === 0)) return null

  return (
    <div
      className="flex flex-col rounded-xl border border-[var(--color-border)] bg-[var(--color-card)] p-5 shadow-[var(--shadow-card)]"
      role="region"
      aria-label="Active guest residencies"
    >
      {/* Header */}
      <p className="text-[11px] font-bold uppercase tracking-[0.08em] text-[var(--color-muted-foreground)]">
        Guest residency
      </p>

      {/* Rows */}
      <div className="mt-4">
        {preview ? (
          <div className="space-y-4">
            {Array.from({ length: 2 }).map((_, i) => (
              <div key={i} className="space-y-1.5">
                <div className="flex items-center gap-2">
                  <div className="h-7 w-7 rounded-full bg-[var(--color-muted)]" />
                  <div className="h-3 w-24 rounded bg-[var(--color-muted)]" />
                  <div className="ml-auto h-3 w-12 rounded bg-[var(--color-muted)]" />
                </div>
                <div className="h-1 w-full rounded-full bg-[var(--color-muted)]" />
              </div>
            ))}
          </div>
        ) : (
          <ul className="space-y-4" role="list">
            {(data?.rows ?? []).map((row) => {
              // Days-remaining bar: full = 90 days residency as baseline
              const RESIDENCY_BASELINE_DAYS = 90
              const barPct = Math.min(100, Math.round((row.daysRemaining / RESIDENCY_BASELINE_DAYS) * 100))
              const isEnding = row.daysRemaining <= 7

              return (
                <li key={row.artistId}>
                  <button
                    type="button"
                    onClick={() => router.push(`/team/${row.artistId}`)}
                    className="w-full space-y-1.5 text-left focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-[var(--color-ring)] focus-visible:ring-offset-1 rounded"
                    aria-label={`${row.name}: ${row.daysRemaining} days remaining, ${row.bookingsDuringResidency} bookings`}
                  >
                    <div className="flex items-center gap-2">
                      <ArtistAvatar name={row.name} avatarUrl={row.avatarUrl} />
                      <div className="min-w-0 flex-1">
                        <p className="truncate text-[13px] font-medium text-[var(--color-foreground)]">
                          {row.name}
                        </p>
                        <p
                          className={cn(
                            'text-[10px] tabular-nums',
                            isEnding ? 'text-[var(--color-rust)]' : 'text-[var(--color-muted-foreground)]',
                          )}
                        >
                          {row.daysRemaining}d left · {row.bookingsDuringResidency} booking{row.bookingsDuringResidency !== 1 ? 's' : ''}
                        </p>
                      </div>
                    </div>

                    {/* Days remaining bar */}
                    <div
                      className="h-1 w-full overflow-hidden rounded-full bg-[var(--color-muted)]"
                      role="progressbar"
                      aria-valuenow={barPct}
                      aria-valuemin={0}
                      aria-valuemax={100}
                    >
                      <div
                        className={cn(
                          'h-full rounded-full transition-all duration-300',
                          isEnding ? 'bg-[var(--color-rust)]' : 'bg-[var(--color-onyx)]',
                        )}
                        style={{ width: `${barPct}%` }}
                      />
                    </div>
                  </button>
                </li>
              )
            })}
          </ul>
        )}
      </div>
    </div>
  )
}

