/**
 * Server-side data fetcher for ArtistUtilizationWidget.
 * Computes booked minutes / scheduled available minutes * 100 per artist this week.
 */

type SupabaseClient = Awaited<ReturnType<typeof import('@/lib/supabase/server').createClient>>

// ─── Types ────────────────────────────────────────────────────────────────────

export interface ArtistUtilRow {
  artistId: string
  name: string
  /** URL to artist avatar (may be null) */
  avatarUrl: string | null
  /** 'staff' | 'guest' */
  type: 'staff' | 'guest'
  /** 0–100 */
  utilizationPct: number
  bookedMinutes: number
  availableMinutes: number
}

export interface ArtistUtilizationData {
  rows: ArtistUtilRow[]
  weekLabel: string
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

function isoWeekMonday(ref: Date): Date {
  const d = new Date(ref)
  d.setUTCHours(0, 0, 0, 0)
  const day = d.getUTCDay()
  const diffToMon = day === 0 ? -6 : 1 - day
  d.setUTCDate(d.getUTCDate() + diffToMon)
  return d
}

// ─── Main fetch ───────────────────────────────────────────────────────────────

export async function getArtistUtilizationData(
  supabase: SupabaseClient,
  studioId: string,
): Promise<ArtistUtilizationData> {
  const now = new Date()
  const weekStart = isoWeekMonday(now)
  const weekEnd = new Date(weekStart)
  weekEnd.setUTCDate(weekEnd.getUTCDate() + 7)

  const startIso = weekStart.toISOString()
  const endIso = weekEnd.toISOString()

  // Fetch artists + their bookings this week in parallel
  // artists table uses `status` column — active artists have status='active'
  const [artistsRes, bookingsRes] = await Promise.all([
    supabase
      .from('artists')
      .select('id, display_name, avatar_url')
      .eq('studio_id', studioId)
      .eq('status', 'active'),

    supabase
      .from('bookings')
      .select('artist_id, duration_min, status, scheduled_at')
      .eq('studio_id', studioId)
      .gte('scheduled_at', startIso)
      .lt('scheduled_at', endIso)
      .in('status', ['confirmed', 'completed', 'in_progress']),
  ])

  const artists = artistsRes.data ?? []
  const bookings = bookingsRes.data ?? []

  // Default available hours per artist for the week if no schedule data: 8h × 5 days
  const DEFAULT_WEEKLY_AVAILABLE_MINUTES = 8 * 60 * 5

  // Aggregate booked minutes per artist
  const bookedMap = new Map<string, number>()
  for (const b of bookings) {
    const current = bookedMap.get(b.artist_id) ?? 0
    bookedMap.set(b.artist_id, current + (b.duration_min ?? 0))
  }

  const rows: ArtistUtilRow[] = artists.map((a) => {
    const bookedMinutes = bookedMap.get(a.id) ?? 0
    const availableMinutes = DEFAULT_WEEKLY_AVAILABLE_MINUTES
    const utilizationPct = Math.min(
      100,
      Math.round((bookedMinutes / availableMinutes) * 100),
    )

    return {
      artistId: a.id,
      name: a.display_name,
      avatarUrl: a.avatar_url ?? null,
      // artists table has no 'type' column — all are 'staff' at DB level
      // guest artist tracking is done via guest_artist_engagements table
      type: 'staff' as const,
      utilizationPct,
      bookedMinutes,
      availableMinutes,
    }
  })

  // Sort: highest utilization first
  rows.sort((a, b) => b.utilizationPct - a.utilizationPct)

  const weekLabel = weekStart.toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
  })

  return { rows, weekLabel }
}

/**
 * Server-side data fetcher for LowInventoryWidget.
 * Returns inventory items below their min_threshold.
 * Returns null when no items are below threshold (widget should not render).
 *
 * Column names from generated types:
 *   current_stock   (quantity on hand)
 *   min_threshold   (reorder threshold)
 */

type SupabaseClient = Awaited<ReturnType<typeof import('@/lib/supabase/server').createClient>>

// ─── Types ────────────────────────────────────────────────────────────────────

export interface LowInventoryRow {
  itemId: string
  name: string
  sku: string | null
  currentStock: number
  reorderThreshold: number
  /** Days since last reorder — always null (no last_reorder_at column in schema) */
  daysSinceReorder: number | null
}

export interface LowInventoryData {
  rows: LowInventoryRow[]
}

// ─── Main fetch ───────────────────────────────────────────────────────────────

export async function getLowInventoryData(
  supabase: SupabaseClient,
  studioId: string,
): Promise<LowInventoryData | null> {
  // Fetch all active items and filter in application layer
  // (PostgREST doesn't support column-to-column comparison without a generated column/view)
  const { data: allItems } = await supabase
    .from('inventory_items')
    .select('id, name, sku, current_stock, min_threshold')
    .eq('studio_id', studioId)
    .eq('is_active', true)
    .order('current_stock', { ascending: true })

  if (!allItems) return null

  // Filter to items below threshold, cap at 6
  const lowItems = allItems
    .filter((item) => item.current_stock < item.min_threshold)
    .slice(0, 6)

  if (lowItems.length === 0) return null

  const rows: LowInventoryRow[] = lowItems.map((r) => ({
    itemId: r.id,
    name: r.name,
    sku: r.sku,
    currentStock: r.current_stock,
    reorderThreshold: r.min_threshold,
    daysSinceReorder: null, // no last_reorder_at column in current schema
  }))

  return { rows }
}

/**
 * Server-side data fetcher for GuestResidencyWidget.
 * Returns active guest artist residencies.
 * Returns null when no active residencies exist (widget should not render).
 *
 * TODO: The artists table does not yet have `type` or `residency_end_at` columns.
 * Guest residency data lives in `guest_artist_engagements` — query that table instead.
 * For now, this loader checks guest_artist_engagements and returns null gracefully
 * if the table structure doesn't match.
 */

type SupabaseClient = Awaited<ReturnType<typeof import('@/lib/supabase/server').createClient>>

// ─── Types ────────────────────────────────────────────────────────────────────

export interface GuestResidencyRow {
  artistId: string
  name: string
  avatarUrl: string | null
  residencyEndAt: string
  daysRemaining: number
  bookingsDuringResidency: number
}

export interface GuestResidencyData {
  rows: GuestResidencyRow[]
}

// ─── Main fetch ───────────────────────────────────────────────────────────────

export async function getGuestResidencyData(
  supabase: SupabaseClient,
  studioId: string,
): Promise<GuestResidencyData | null> {
  const nowIso = new Date().toISOString()

  // Query guest_artist_engagements — if this table doesn't have these columns
  // the query will error and we return null gracefully
  const { data, error } = await supabase
    .from('guest_artist_engagements')
    .select(`
      id,
      end_date,
      artists!inner(id, display_name, avatar_url)
    `)
    .eq('studio_id', studioId)
    .eq('status', 'active')
    .gt('end_date', nowIso)
    .order('end_date', { ascending: true })
    .limit(5)

  if (error || !data || data.length === 0) return null

  type EngagementRow = {
    id: string
    end_date: string
    artists: {
      id: string
      display_name: string
      avatar_url: string | null
    }
  }

  const engagements = data as unknown as EngagementRow[]
  const artistIds = engagements.map((e) => e.artists.id)

  // Booking counts since residency start (week as proxy)
  const weekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString()
  const { data: bookingCounts } = await supabase
    .from('bookings')
    .select('artist_id')
    .eq('studio_id', studioId)
    .in('artist_id', artistIds)
    .gte('scheduled_at', weekAgo)
    .in('status', ['confirmed', 'completed', 'in_progress'])

  const countMap = new Map<string, number>()
  for (const b of bookingCounts ?? []) {
    countMap.set(b.artist_id, (countMap.get(b.artist_id) ?? 0) + 1)
  }

  const rows: GuestResidencyRow[] = engagements.map((e) => {
    const endMs = new Date(e.end_date).getTime()
    const daysRemaining = Math.max(0, Math.ceil((endMs - Date.now()) / (1000 * 60 * 60 * 24)))
    return {
      artistId: e.artists.id,
      name: e.artists.display_name,
      avatarUrl: e.artists.avatar_url,
      residencyEndAt: e.end_date,
      daysRemaining,
      bookingsDuringResidency: countMap.get(e.artists.id) ?? 0,
    }
  })

  return rows.length > 0 ? { rows } : null
}

