/**
 * Server-side data fetcher for GuestResidencyWidget.
 * Returns active guest artist residencies from guest_artist_engagements.
 * Returns null when no active residencies exist (widget should not render).
 */

type SupabaseClient = Awaited<ReturnType<typeof import('@/lib/supabase/server').createClient>>

// ─── Types ────────────────────────────────────────────────────────────────────

export interface GuestResidencyRow {
  artistId: string
  name: string
  avatarUrl: string | null
  residencyEndAt: string
  daysRemaining: number
  bookingsDuringResidency: number
}

export interface GuestResidencyData {
  rows: GuestResidencyRow[]
}

// ─── Main fetch ───────────────────────────────────────────────────────────────

export async function getGuestResidencyData(
  supabase: SupabaseClient,
  studioId: string,
): Promise<GuestResidencyData | null> {
  const nowIso = new Date().toISOString()

  const { data, error } = await supabase
    .from('guest_artist_engagements')
    .select(`
      id,
      end_date,
      booking_count,
      artists!inner(id, display_name, avatar_url)
    `)
    .eq('studio_id', studioId)
    .eq('status', 'active')
    .gt('end_date', nowIso)
    .order('end_date', { ascending: true })
    .limit(5)

  if (error || !data || data.length === 0) return null

  type EngagementRow = {
    id: string
    end_date: string
    booking_count: number
    artists: {
      id: string
      display_name: string
      avatar_url: string | null
    }
  }

  const engagements = data as unknown as EngagementRow[]

  const rows: GuestResidencyRow[] = engagements.map((e) => {
    const endMs = new Date(e.end_date).getTime()
    const daysRemaining = Math.max(0, Math.ceil((endMs - Date.now()) / (1000 * 60 * 60 * 24)))
    return {
      artistId: e.artists.id,
      name: e.artists.display_name,
      avatarUrl: e.artists.avatar_url,
      residencyEndAt: e.end_date,
      daysRemaining,
      bookingsDuringResidency: e.booking_count,
    }
  })

  return rows.length > 0 ? { rows } : null
}

'use client'

import { useEffect, useState } from 'react'
import { CalendarDays, CreditCard, DollarSign, Users } from 'lucide-react'
import { KpiCard } from '@/components/shared/KpiCard'
import { KpiCardSkeleton } from '@/components/shared/KpiCardSkeleton'
import { ActivityFeed } from '@/components/shared/ActivityFeed'
import { AlertsCard } from '@/components/shared/AlertsCard'
import { InventoryAlertsCard } from '@/components/inventory/InventoryAlertsCard'
import { GettingStartedCard } from '@/components/dashboard/GettingStartedCard'
import { TodayAgendaWidget } from '@/components/dashboard/TodayAgendaWidget'
import { QuickActionsRow } from '@/components/dashboard/QuickActionsRow'
import { EmptyDashboardState } from '@/components/dashboard/EmptyDashboardState'
import { useDashboardKpis } from '@/hooks/dashboard/use-dashboard-kpis'
import { useTodayAgenda } from '@/hooks/dashboard/use-today-agenda'
import { useRecentActivity } from '@/hooks/dashboard/use-recent-activity'
import { useInventoryAlerts } from '@/hooks/dashboard/use-inventory-alerts'
import { useDashboardAlerts } from '@/hooks/dashboard/use-dashboard-alerts'
import { useRouter } from 'next/navigation'
import type { GettingStartedCounts } from '@/components/dashboard/GettingStartedCard'
import { RoleAwareHero } from './RoleAwareHero'
import { TodayQuickActionsRow } from './QuickActionsRow'
import { WeekRevenueTrajectoryWidget } from './WeekRevenueTrajectoryWidget'
import { ArtistUtilizationWidget } from './ArtistUtilizationWidget'
import { PendingDepositsWidget } from './PendingDepositsWidget'
import { ConsentStatusWidget } from './ConsentStatusWidget'
import { LowInventoryWidget } from './LowInventoryWidget'
import { GuestResidencyWidget } from './GuestResidencyWidget'
import type { WeekRevenueData } from '@/lib/dashboard/week-revenue'
import type { ArtistUtilizationData } from '@/lib/dashboard/artist-utilization'
import type { PendingDepositsData } from '@/lib/dashboard/pending-deposits'
import type { ConsentStatusData } from '@/lib/dashboard/consent-status'
import type { LowInventoryData } from '@/lib/dashboard/low-inventory'
import type { GuestResidencyData } from '@/lib/dashboard/guest-residency'
import type { Database } from '@/lib/supabase/types'

type StudioRole = Database['public']['Tables']['studio_members']['Row']['role']

interface TodayClientProps {
  firstName: string
  studioName: string
  hasStudio: boolean
  studioId: string | null
  role: StudioRole
  ownArtistId?: string | null
  artistEarningsToday?: number
  gettingStartedCounts: GettingStartedCounts
  /** Wave 2 S2.2: Week revenue trajectory */
  weekRevenue?: WeekRevenueData | null
  /** Wave 2 S2.2: Artist utilization */
  artistUtil?: ArtistUtilizationData | null
  /** Wave 2 S2.2: Pending deposits */
  pendingDeposits?: PendingDepositsData | null
  /** Wave 2 S2.2: Consent status */
  consentStatus?: ConsentStatusData | null
  /** Wave 2 S2.2: Low inventory (null = no low items, widget hidden) */
  lowInventory?: LowInventoryData | null
  /** Wave 2 S2.2: Guest residency (null = no active residencies, widget hidden) */
  guestResidency?: GuestResidencyData | null
}

function formatDate(): string {
  return new Date().toLocaleDateString('en-US', {
    weekday: 'long',
    month: 'long',
    day: 'numeric',
  })
}

export function TodayClient({
  firstName,
  studioName,
  hasStudio,
  studioId,
  role,
  ownArtistId,
  artistEarningsToday = 0,
  gettingStartedCounts,
  weekRevenue = null,
  artistUtil = null,
  pendingDeposits = null,
  consentStatus = null,
  lowInventory = null,
  guestResidency = null,
}: TodayClientProps) {
  const router = useRouter()
  const kpisQuery = useDashboardKpis(hasStudio)
  const agendaQuery = useTodayAgenda(hasStudio)
  const activityQuery = useRecentActivity(hasStudio)
  const inventoryAlertsQuery = useInventoryAlerts(hasStudio)
  const alertsQuery = useDashboardAlerts(hasStudio)

  const kpis = kpisQuery.data
  const kpisLoading = kpisQuery.isLoading || kpisQuery.isFetching

  const [dismissedIds, setDismissedIds] = useState<string[]>([])

  const [checklistDismissed, setChecklistDismissed] = useState(false)
  useEffect(() => {
    setChecklistDismissed(
      localStorage.getItem('inkos:getting-started:dismissed') === '1',
    )
  }, [])

  // N shortcut — new appointment
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement
      const tag = target.tagName
      if (
        tag === 'INPUT' ||
        tag === 'TEXTAREA' ||
        tag === 'SELECT' ||
        target.isContentEditable
      )
        return
      if (e.key === 'n' || e.key === 'N') {
        e.preventDefault()
        router.push('/appointments/new')
      }
    }
    window.addEventListener('keydown', handler)
    return () => window.removeEventListener('keydown', handler)
  }, [router])

  const visibleAlerts = (alertsQuery.data ?? []).filter(
    (a) => !dismissedIds.includes(a.id),
  )

  const showEmptyState =
    checklistDismissed && gettingStartedCounts.bookings === 0

  const revenueMtd = kpis?.revenueMtd ?? 0
  const revenueMtdDelta = kpis?.revenueMtdDelta ?? '0%'
  const apptTodayCount = kpis?.apptTodayCount ?? 0
  const apptTodayCompleted = kpis?.apptTodayCompleted ?? 0
  const apptTodayPending = kpis?.apptTodayPending ?? 0
  const newClientsMtd = kpis?.newClientsMtd ?? 0
  const newClientsMtdDelta = kpis?.newClientsMtdDelta ?? '0%'
  const pendingDepositsTotal = kpis?.pendingDepositsTotal ?? 0
  const pendingDepositsCount = kpis?.pendingDepositsCount ?? 0
  const pendingDepositsDelta = kpis?.pendingDepositsDelta ?? '0%'

  const agendaAppointments = agendaQuery.data ?? []
  const totalToday = agendaAppointments.length

  // KPI row: owner/admin only — artists see earnings inside RoleAwareHero
  const showKpis = role === 'owner' || role === 'admin'

  return (
    <div className="min-h-full bg-[var(--color-page-bg)]">
      <div className="mx-auto max-w-[1440px] space-y-6 px-4 pb-10 pt-6 sm:px-6 lg:px-8">

        {/* ── Header ── */}
        <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
          <div>
            <p className="mb-1 text-[11px] font-bold uppercase tracking-[0.08em] text-stone-brand">
              {studioName}
            </p>
            <h1 className="font-display text-[52px] leading-[1.05] text-foreground">
              The studio,{' '}
              <span className="font-serif-italic text-rust">at a glance.</span>
            </h1>
            <p className="mt-2 text-sm text-stone-brand">{formatDate()} · Good to see you, {firstName}.</p>
          </div>
        </div>

        {/* ── Today quick actions (card grid with descriptions) ── */}
        <TodayQuickActionsRow />

        {/* ── Legacy quick actions toolbar (shortcut buttons) ── */}
        <QuickActionsRow />

        {/* ── Getting started checklist ── */}
        <GettingStartedCard counts={gettingStartedCounts} />

        {showEmptyState ? (
          <EmptyDashboardState />
        ) : (
          <>
            {/* ── Role-aware hero: TodayQueue + role-specific widgets ── */}
            {hasStudio && studioId && (
              <RoleAwareHero
                role={role}
                studioId={studioId}
                ownArtistId={ownArtistId}
                artistEarningsToday={artistEarningsToday}
                inventoryAlerts={inventoryAlertsQuery.data}
              />
            )}

            {/* ── KPI row — owner/admin only ── */}
            {showKpis && (
              <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
                {kpisLoading ? (
                  Array.from({ length: 4 }).map((_, i) => <KpiCardSkeleton key={i} />)
                ) : (
                  <>
                    <KpiCard
                      label="Revenue MTD"
                      value={revenueMtd}
                      formatter={(n) =>
                        n >= 100_000
                          ? `$${(n / 100_000).toFixed(1)}k`
                          : `$${(n / 100).toLocaleString()}`
                      }
                      delta={revenueMtdDelta}
                      trend={revenueMtdDelta.startsWith('+') ? 'up' : 'down'}
                      subtextLabel="vs last month"
                      {...(kpis?.revenueDailyLast30 !== undefined ? { sparkline: kpis.revenueDailyLast30 } : {})}
                      icon={DollarSign}
                      accentVar="var(--color-rust)"
                      hoverVariant="lift"
                      index={0}
                    />
                    <div
                      role="link"
                      tabIndex={0}
                      onClick={() =>
                        document
                          .getElementById('today-agenda')
                          ?.scrollIntoView({ behavior: 'smooth' })
                      }
                      onKeyDown={(e) => {
                        if (e.key === 'Enter') {
                          document
                            .getElementById('today-agenda')
                            ?.scrollIntoView({ behavior: 'smooth' })
                        }
                      }}
                      className="cursor-pointer"
                      aria-label="Scroll to today's agenda"
                    >
                      <KpiCard
                        label="Appointments Today"
                        value={apptTodayCount}
                        subtextLabel={`${apptTodayCompleted} completed · ${apptTodayPending} pending`}
                        icon={CalendarDays}
                        trend="neutral"
                        accentVar="var(--color-foreground)"
                        hoverVariant="lift"
                        index={1}
                      />
                    </div>
                    <KpiCard
                      label="New Clients MTD"
                      value={newClientsMtd}
                      delta={newClientsMtdDelta}
                      trend={newClientsMtdDelta.startsWith('+') ? 'up' : 'down'}
                      subtextLabel="vs last month"
                      {...(kpis?.newClientsDailyLast30 !== undefined ? { sparkline: kpis.newClientsDailyLast30 } : {})}
                      icon={Users}
                      accentVar="var(--color-foreground)"
                      hoverVariant="lift"
                      index={2}
                    />
                    <KpiCard
                      label="Pending Deposits"
                      value={pendingDepositsTotal}
                      formatter={(n) =>
                        n >= 100_000
                          ? `$${(n / 100_000).toFixed(1)}k`
                          : `$${(n / 100).toLocaleString()}`
                      }
                      delta={pendingDepositsDelta}
                      trend={pendingDepositsCount > 0 ? 'up' : 'down'}
                      invertTrend
                      subtextLabel={`${pendingDepositsCount} booking${pendingDepositsCount !== 1 ? 's' : ''}`}
                      icon={CreditCard}
                      accentVar="var(--color-stone-brand)"
                      hoverVariant="lift"
                      index={3}
                    />
                  </>
                )}
              </div>
            )}

            {/* ── Wave 2 S2.2: Revenue trajectory + Artist utilization ── */}
            {showKpis && (weekRevenue || artistUtil) && (
              <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
                {weekRevenue && (
                  <WeekRevenueTrajectoryWidget data={weekRevenue} />
                )}
                {artistUtil && (
                  <ArtistUtilizationWidget data={artistUtil} />
                )}
              </div>
            )}

            {/* ── Wave 2 S2.2: Pending deposits + Consent + conditional widgets ── */}
            {showKpis && (pendingDeposits || consentStatus || lowInventory || guestResidency) && (
              <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
                {pendingDeposits && (
                  <PendingDepositsWidget data={pendingDeposits} />
                )}
                {consentStatus && (
                  <ConsentStatusWidget data={consentStatus} />
                )}
                <LowInventoryWidget data={lowInventory ?? null} />
                <GuestResidencyWidget data={guestResidency ?? null} />
              </div>
            )}

            {/* ── Agenda + Activity ── */}
            <div className="grid grid-cols-1 gap-4 lg:grid-cols-12">
              <div id="today-agenda" className="lg:col-span-8">
                <TodayAgendaWidget
                  appointments={agendaAppointments}
                  totalToday={totalToday}
                  loading={agendaQuery.isLoading}
                />
              </div>
              <div className="lg:col-span-4">
                <ActivityFeed
                  events={activityQuery.data ?? []}
                  loading={activityQuery.isLoading}
                  {...(studioId !== null ? { studioId } : {})}
                />
              </div>
            </div>

            {/* ── Alerts ── */}
            <div className="grid grid-cols-1 gap-4">
              <AlertsCard
                alerts={visibleAlerts}
                loading={alertsQuery.isLoading}
                onDismiss={(id) =>
                  setDismissedIds((prev) => [...prev, id])
                }
              />
              {inventoryAlertsQuery.data != null && (
                <InventoryAlertsCard
                  openAlertsCount={inventoryAlertsQuery.data.open_alerts_count}
                  itemsBelowThreshold={inventoryAlertsQuery.data.items_below_threshold}
                  loading={inventoryAlertsQuery.isLoading}
                />
              )}
            </div>
          </>
        )}

      </div>
    </div>
  )
}

