export async function updateProjectStatusAction(
  projectId: string,
  newStatus: ProjectStatus
): Promise<ActionResult<void>> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { ok: false, error: 'Not authenticated' }
  if (!canWrite(auth.role as ReadRole)) return { ok: false, error: 'Insufficient permissions' }

  const supabase = await createClient()

  // Fetch current status for the activity log
  const { data: current, error: fetchErr } = await supabase
    .from('projects')
    .select('status')
    .eq('id', projectId)
    .eq('studio_id', auth.studioId)
    .single()

  if (fetchErr || !current) {
    return { ok: false, error: 'Project not found' }
  }

  const prevStatus = current.status

  // Update status
  const { error: updateErr } = await supabase
    .from('projects')
    .update({ status: newStatus, updated_at: new Date().toISOString() })
    .eq('id', projectId)
    .eq('studio_id', auth.studioId)

  if (updateErr) {
    logger.error({ updateErr, projectId }, 'updateProjectStatusAction update failed')
    return { ok: false, error: 'Failed to update status' }
  }

  // Append activity log row
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  await (supabase as any)
    .from('project_activity_log')
    .insert({
      project_id: projectId,
      actor_id: auth.user.id,
      event_type: 'status_changed',
      details: { prev_status: prevStatus, new_status: newStatus },
    })

  revalidatePath('/projects')
  revalidatePath(`/projects/${projectId}`)
  return { ok: true, data: undefined }
